dslRule:
/*!
@id: org.eclipse.jface.text.add-read-loop-termination-condition
@description: Add termination condition 'c != -1' to a specific read loop to prevent hang.
@severity: WARNING
*/
while (!fReadFromBuffer)
=>
while (!fReadFromBuffer && c != -1)
;;

beforeExample:
class SubstitutionTextReader extends java.io.Reader {
    private boolean fReadFromBuffer;
    private int c;
    private int nextChar() { return -1; }
    public int read(char[] cbuf, int off, int len) throws java.io.IOException {
        do {
            c = nextChar();
            while (!fReadFromBuffer) {
                String s = "test";
                if (s == null) break;
            }
        } while (c != -1);
        return 0;
    }
}

afterExample:
class SubstitutionTextReader extends java.io.Reader {
    private boolean fReadFromBuffer;
    private int c;
    private int nextChar() { return -1; }
    public int read(char[] cbuf, int off, int len) throws java.io.IOException {
        do {
            c = nextChar();
            while (!fReadFromBuffer && c != -1) {
                String s = "test";
                if (s == null) break;
            }
        } while (c != -1);
        return 0;
    }
}

negativeExample:
class OtherClass {
    private boolean someOtherFlag;
    public void method() {
        int x = 0;
        while (!someOtherFlag) { 
            x++;
        }
    }
}
